package play.gradle

import org.gradle.testkit.runner.GradleRunner
import java.io.File

/**
 * Shared helpers for the TestKit functional tests. Each test builds a temporary
 * consumer project under a JUnit @TempDir, applies the Play1 plugin via
 * withPluginClasspath() (the classpath generated by java-gradle-plugin), and
 * runs real Gradle invocations against it.
 */
object TestProject {

    /**
     * Write a minimal consumer project into [dir]: a settings.gradle.kts and a
     * build.gradle.kts that applies id("org.playframework.play1"). [play1Block]
     * is the body of the play1 { } configuration block (may be empty).
     *
     * The plugin applies the `java` plugin and pins a Java 25 toolchain, so the
     * consumer build needs a settings name; no source dirs are required for the
     * tasks under test (none compile or fork a JVM here).
     */
    fun write(dir: File, play1Block: String = "") {
        File(dir, "settings.gradle.kts").writeText(
            """
            rootProject.name = "testapp"
            """.trimIndent() + "\n"
        )
        File(dir, "build.gradle.kts").writeText(
            """
            plugins {
                id("org.playframework.play1")
            }

            play1 {
            $play1Block
            }
            """.trimIndent() + "\n"
        )
    }

    /**
     * PF-230: Gradle's test task runs an application's tests with framework/lib's JUnit Platform
     * jars, which a fake framework lacks: copy this checkout's into [frameworkLib].
     */
    fun copyJUnitPlatform(frameworkLib: File) {
        val real = File("../../framework/lib")
        real.listFiles { f -> Regex("(junit|opentest4j|apiguardian)-.*\\.jar").matches(f.name) }!!
            .forEach { it.copyTo(File(frameworkLib, it.name), overwrite = true) }
    }

    /**
     * A test class, ProbeTest, whose one test prints [lines] (Java expressions) to its JVM's
     * stdout, which Gradle's test task keeps in the class's JUnit XML: see [probeOutput].
     */
    fun writeProbeTest(app: File, vararg lines: String) {
        val prints = lines.joinToString("\n") { "        System.out.println($it);" }
        File(app, "test").mkdirs()
        File(app, "test/ProbeTest.java").writeText(
            "public class ProbeTest {\n    @org.junit.jupiter.api.Test\n    public void report() {\n$prints\n    }\n}\n"
        )
    }

    /** What ProbeTest printed in the test task's last run, or "" when it did not run. */
    fun probeOutput(app: File): String =
        File(app, "build/test-results/test/TEST-ProbeTest.xml").let { if (it.isFile) it.readText() else "" }

    fun runner(dir: File, vararg args: String): GradleRunner =
        GradleRunner.create()
            .withProjectDir(dir)
            .withPluginClasspath()
            // TestKit reuses a long-lived test daemon by default; the consumer
            // builds here are configuration-only, but pinning --no-configuration-cache
            // keeps task-graph assertions (tasks --all) deterministic across runs.
            .withArguments(*args)
            .forwardOutput()
}
